import { NEON_SERVICES, NEON_SERVICE_LABELS } from "../neon_services.js";
import { BRANCH_ENV_KEYS, ENV_PULL_KEYS, isLegacyFunctionBaseUrlKey, serviceForEnvKey } from "../env_services.js";
import { isAbsolute, relative } from "node:path";
import { homedir } from "node:os";
import chalk from "chalk";
// src/commands/env_output.ts
/** Wide enough for the longest label ("Object Storage") plus a gutter, so blocks align. */
const LABEL_WIDTH = 16;
const row = (label, value) => `  ${label.padEnd(LABEL_WIDTH)}${value}`;
/** Relative to `cwd` when the file is inside it, else absolute with the home directory as `~`. */
const displayPath = (file, cwd) => {
	const rel = relative(cwd, file);
	if (rel !== "" && !rel.startsWith("..") && !isAbsolute(rel)) return rel;
	const home = homedir();
	return file.startsWith(`${home}/`) ? `~${file.slice(home.length)}` : file;
};
const BRANCH_GROUP = "Branch";
const OTHER_GROUP = "Other";
const GROUP_ORDER = [
	NEON_SERVICE_LABELS.postgres,
	BRANCH_GROUP,
	...NEON_SERVICES.filter((service) => service !== "postgres").map((service) => NEON_SERVICE_LABELS[service]),
	OTHER_GROUP
];
const groupOf = (key) => {
	if (BRANCH_ENV_KEYS.includes(key)) return BRANCH_GROUP;
	if (isLegacyFunctionBaseUrlKey(key)) return NEON_SERVICE_LABELS.functions;
	const pullKey = ENV_PULL_KEYS.find((candidate) => candidate === key);
	const service = pullKey ? serviceForEnvKey(pullKey) : null;
	return service ? NEON_SERVICE_LABELS[service] : OTHER_GROUP;
};
/** Canonical key order, so a row reads the same whether a key was rewritten or reused. */
const keyRank = (key) => {
	const index = ENV_PULL_KEYS.findIndex((candidate) => candidate === key);
	return index === -1 ? ENV_PULL_KEYS.length : index;
};
const byKeyRank = (a, b) => keyRank(a) - keyRank(b) || a.localeCompare(b);
const groupKeys = (keys) => {
	const groups = /* @__PURE__ */ new Map();
	for (const key of [...keys].sort(byKeyRank)) {
		const group = groupOf(key);
		groups.set(group, [...groups.get(group) ?? [], key]);
	}
	return groups;
};
const pulledBranch = (branch) => `branch ${chalk.cyan.bold(branch.branchName)} ${chalk.dim(`(${branch.branchId}${branch.usedDefault ? ", project default" : ""})`)}`;
const formatPulledEnv = (outcome, cwd, branch) => {
	const fresh = new Set(outcome.credential?.fresh ?? []);
	const count = outcome.written.length;
	const source = branch ? ` from ${pulledBranch(branch)}` : "";
	const lines = [`Pulled ${count} Neon variable${count === 1 ? "" : "s"} into ${displayPath(outcome.file, cwd)}${source}`];
	const groups = groupKeys(outcome.written);
	for (const group of GROUP_ORDER) {
		const keys = groups.get(group);
		if (!keys) continue;
		lines.push(row(group, keys.map((key) => fresh.has(key) ? `${key}*` : key).join(", ")));
	}
	if (outcome.removed.length > 0) lines.push(row("Removed", `${outcome.removed.join(", ")} (not produced by this pull)`));
	if (outcome.removed.some(isLegacyFunctionBaseUrlKey)) lines.push(row("", "Use functionBaseUrl(\"<slug>\") from @neon/env instead."));
	if (fresh.size > 0) lines.push("  * new credential value");
	const credential = outcome.credential;
	if (credential?.issued && credential.revoked.length > 0) lines.push(`Revoked the credential it replaced (${credential.revoked.join(", ")}).`);
	else if (credential?.issued && credential.superseded.length > 0) lines.push(`Left the credential it replaced live (${credential.superseded.join(", ")}): an explicitly scoped pull can't tell which other variables still use it. Revoke it in the Neon Console if nothing does.`);
	return `${lines.join("\n")}\n`;
};
export { displayPath, formatPulledEnv, pulledBranch, row };
